    setRo('l16pB', Math.hypot(GEO.target[0] - GEO.box[0], GEO.target[1] - GEO.box[1]).toFixed(2));
    addEventListener('resize', () => { g = fit(cv, 0.96); draw(); });
    addEventListener('themechange', draw);
